let area;

let NUM_SVG_GROUPS = 4, SVG_GRPS;

function setup() {
	createCanvas(windowWidth, windowHeight);
	pixelDensity(1);
	describe('canvas with subdivided areas hatched vertically or horizontally');

	SVG_GRPS = [];
	for (let i = 0; i < NUM_SVG_GROUPS; i++) SVG_GRPS[i] = [];

	initArea();
	loop();
}

