function mRand(v1, v2) {
	const vd = (v2 - v1);
	return floor(v1 + random(vd * 0.3, vd * 0.7))
}
function mFract(v1, v2, f) {
	var vd = (v2 - v1);
	return floor(v1 + vd * f);
}

class Area {
	constructor(pal) {
		this.pal = pal;
		this.objs = [];
		const p1 = createVector(0, 0);
		const p2 = createVector(width, 0);
		const p3 = createVector(width, height);
		const p4 = createVector(0, height);
		const clr = random(this.pal);
		this.objs.push({p1, p2, p3, p4, clr});
	}

	divide() {
		const last = random(this.objs); // this.objs[this.objs.length-1]
		var p1 = last.p1.copy();
		var p2 = last.p2.copy();
		var p3 = last.p3.copy();
		var p4 = last.p4.copy();

		const f1 = random(0.3, 0.7);
		const f2 = random(0.3, 0.7);

		if (random() < 0.5) {
			// horizontal split

			p1.y = mFract(p1.y, p4.y, f1);
			last.p4.y = p1.y
			p1.x = mFract(p1.x, p4.x, f1);
			last.p4.x = p1.x

			p2.y = mFract(p2.y, p3.y, f2);
			last.p3.y = p2.y
			p2.x = mFract(p2.x, p3.x, f2);
			last.p3.x = p2.x

		} else {
			// vertical
			p1.x = mFract(p1.x, p2.x, f1);
			last.p2.x = p1.x
			p1.y = mFract(p1.y, p2.y, f1);
			last.p2.y = p1.y

			p4.x = mFract(p3.x, p4.x, f2);
			last.p3.x = p4.x
			p4.y = mFract(p3.y, p4.y, f2);
			last.p3.y = p4.y
		}

		var clr = random(this.pal);
		this.objs.push({p1, p2, p3, p4, clr});
	}	

	divide_chaos() {
		var last = random(this.objs); // this.objs[this.objs.length-1]
		var p1 = last.p1.copy();
		var p2 = last.p2.copy();
		var p3 = last.p3.copy();
		var p4 = last.p4.copy();

		if (random() < 0.5) {
			// horizontal split
			p1.y = mRand(p1.y, p4.y);
			p2.y = mRand(p2.y, p3.y);
			last.p4.y = p1.y
			last.p3.y = p2.y
		} else {
			// vertical
			p1.x = mRand(p1.x, p2.x);
			p4.x = mRand(p3.x, p4.x);
			last.p2.x = p1.x
			last.p3.x = p4.x
		}

		var clr = random(this.pal);
		this.objs.push({p1, p2, p3, p4, clr});
	}	

	divide_straight_lines() {
		var last = random(this.objs); // this.objs[this.objs.length-1]
		var p1 = last.p1.copy();
		var p2 = last.p2.copy();
		var p3 = last.p3.copy();
		var p4 = last.p4.copy();

		if (random() < 0.5) {
			// horizontal split
			p1.y = mRand(p1.y, p4.y);
			p2.y = p1.y
			last.p4.y = p1.y
			last.p3.y = p1.y
		} else {
			// vertical
			p1.x = mRand(p1.x, p2.x);
			p4.x = p1.x
			last.p2.x = p1.x
			last.p3.x = p1.x
		}

		var clr = random(this.pal);
		this.objs.push({p1, p2, p3, p4, clr});
	}

	show() {
		push();
		// blendMode(DIFFERENCE)
		noStroke();
		for (let o of this.objs) {
			var clr = color(o.clr);
			// clr.setAlpha(128); fill(clr);
			stroke(clr); noFill();
			/*
			quad(o.p1.x, o.p1.y, 
					 o.p2.x, o.p2.y,
					 o.p3.x, o.p3.y, 
					 o.p4.x, o.p4.y)
			*/
			var p1 = o.p1.copy();
			var p2 = o.p2.copy();
			var p3 = o.p3.copy();
			var p4 = o.p4.copy();
			const rot = (~~(p1.x) % 2 === 0); //  [p1, p2, p3, p4] = [p3, p4, p1, p2]
			const dst = rot ? mid(p2.x-p1.x, p3.x-p4.x) : mid(p4.y-p1.y, p3.y-p2.y);
			const num = ~~(dst / 5);
			let svgStr = "";
			for (let i = 0; i < num; i++) {
				const f = i/num;
				const x1 = rot ? lerp(p1.x, p2.x, f) : lerp(p1.x, p4.x, f)
				const y1 = rot ? lerp(p1.y, p2.y, f) : lerp(p1.y, p4.y, f) 
				const x2 = rot ? lerp(p4.x, p3.x, f) : lerp(p2.x, p3.x, f)
				const y2 = rot ? lerp(p4.y, p3.y, f) : lerp(p2.y, p3.y, f)
				line(x1, y1, x2, y2);
				svgStr += `<line x1="${nf(x1,0,3)}" y1="${nf(y1,0,3)}" x2="${nf(x2,0,3)}" y2="${nf(y2,0,3)}" />\n`;
			}
			const svgGr = `<g>\n${svgStr}</g>\n`
			SVG_GRPS[~~random(NUM_SVG_GROUPS)].push(svgGr);
		}

		pop();
	}
}

function mid(a, b) {
	return lerp(a, b, 0.5);
}

function keyPressed() {
	if (key === "s") {
		// console.log(key);

		let grStr = "";
		for (const gr of SVG_GRPS) {
			grStr += `<g stroke="blue" fill="none">\n`;
			for (const el of gr) {
				grStr += `${el}\n`;
			}
			grStr += `</g>\n`;
		}
		var svgStr = `<svg width="${width}" height="${height}" xmlns="http://www.w3.org/2000/svg">\n${grStr}\n</svg>`;
		// console.log(svgStr)
		save(svgStr.split("\n"), "epi_hatched_areas.svg.txt")

	}
}
